    ll g, x, y, z;
    cin >> g >> x >> y >> z;

    const int width = m - b + 1;
    vector<ll> horizontal(static_cast<size_t>(n) * width);
    vector<pair<ll, int>> que(max(n, m));

    for (int i = 0; i < n; ++i) {
        int head = 0, tail = 0;

        for (int j = 0; j < m; ++j) {
            const ll value = g;

            while (head < tail && que[tail - 1].first >= value)
                --tail;
            que[tail++] = {value, j};

            while (head < tail && que[head].second <= j - b)
                ++head;

            if (j >= b - 1)
                horizontal[static_cast<size_t>(i) * width + j - b + 1] =
                    que[head].first;

            if (i != n - 1 || j != m - 1)
                g = static_cast<ll>((static_cast<__int128>(g) * x + y) % z);
        }
    }

    ll answer = 0;

    for (int j = 0; j < width; ++j) {
        int head = 0, tail = 0;

        for (int i = 0; i < n; ++i) {
            const ll value = horizontal[static_cast<size_t>(i) * width + j];

            while (head < tail && que[tail - 1].first >= value)
                --tail;
            que[tail++] = {value, i};

            while (head < tail && que[head].second <= i - a)
                ++head;

            if (i >= a - 1)
                answer += que[head].first;
        }
    }

    cout << answer << '\n';
    return 0;
}

