    vector<ll> horizontal(static_cast<size_t>(n) * width);
    vector<int> q(m);

    for (int i = 0; i < n; ++i) {
        int head = 0, tail = 0;

        for (int j = 0; j < m; ++j) {
            if (i != 0 || j != 0)
                g = (g * x + y) % z;

            while (head < tail &&
                   horizontal[static_cast<size_t>(i) * width + q[tail - 1]] >= g)
                --tail;

            q[tail++] = j;

            while (head < tail && q[head] <= j - b)
                ++head;

            if (j >= b - 1) {
                horizontal[static_cast<size_t>(i) * width + (j - b + 1)] =
                    horizontal[static_cast<size_t>(i) * width + q[head]];
            }

            horizontal[static_cast<size_t>(i) * width + j] = g;
        }
    }

    ll answer = 0;
    q.resize(n);

    for (int j = 0; j < width; ++j) {
        int head = 0, tail = 0;

        for (int i = 0; i < n; ++i) {
            ll value = horizontal[static_cast<size_t>(i) * width + j];

            while (head < tail &&
                   horizontal[static_cast<size_t>(q[tail - 1]) * width + j] >= value)
                --tail;

            q[tail++] = i;

            while (head < tail && q[head] <= i - a)
                ++head;

            if (i >= a - 1)
                answer += horizontal[static_cast<size_t>(q[head]) * width + j];
        }
    }

    cout << answer << '\n';
    return 0;
}

